  "translations": {
    "L0001": "Met again beneath the bridge once the rain had stopped.",
    "L0002": "Heading back alone today—that's the plan.",
    "L0003": "He said softly, “That's enough now.”",
    "L0004": "Can't tell whether those words meant forgiveness or resignation.",
    "L0005": "Might cross the same bridge again tomorrow.",
    "L0006": "Only the two characters 東京 remained."
  },
